<span class="line">            Player<span class="token operator">*</span> watcher <span class="token operator">=</span> <span class="token class-name">PlayerManager</span><span class="token double-colon punctuation">::</span><span class="token function">Instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">GetPlayer</span><span class="token punctuation">(</span>pair<span class="token punctuation">.</span>first<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
